    best=max(dist,key=lambda p:dist[p]); end=best
    out=[row[:] for row in I]
    cur=end
    while True:
        out[cur[0]][cur[1]]=3
        nxt=par.get(cur)
        if nxt is None or dist.get(nxt)==0: break
        cur=nxt
    return out
for name,(I,O) in [('d5',(I5,O5)),('d6',(I6,O6))]:
    S=solve(I)
    print(name,S==O,[ (r,c,I[r][c],S[r][c],O[r][c]) for r in range(len(I)) for c in range(len(I[0])) if S[r][c]!=O[r][c]])[:25]

def solve(I):
    H,W=len(I),len(I[0])
    twos={(r,c) for r in range(H) for c in range(W) if I[r][c]==2}
    threes={(r,c) for r in range(H) for c in range(W) if I[r][c]==3}
    cnt=collections.Counter(v for row in I for v in row); bgv=cnt.most_common(1)[0][0]
    dist={}; par={}; q=dq()
    for t in twos:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(t[0]+dr,t[1]+dc)
            if 0<=n[0]<H and 0<=n[1]<W and I[n[0]][n[1]]==bgv and n not in dist:
                dist[n]=1; par[n]=t; q.append(n)
    def done(r,c): return any(0<=r+dr<H and 0<=c+dc<W and (r+dr,c+dc) in threes for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
    while q:
        r,c=q.popleft()
        if done(r,c): break
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(r+dr,c+dc)
            if 0<=n[0]<H and 0<=n[1]<W and n not in dist and I[n[0]][n[1]]==bgv:
                dist[n]=dist[(r,c)]+1; par[n]=(r,c); q.append(n)
    best=max(dist,key=lambda p:dist[p]); end=best
    out=[row[:] for row in I]; cur=end
    while dist.get(cur,0)>0:
        out[cur[0]][cur[1]]=3
        cur=par.get(cur,(cur))
        if cur is None: break
        # stop walking once back at a seeded cell whose par is a marker
        if par.get(cur) in twos: break
    return out
for name,(I,O) in [('d5',(I5,O5)),('d6',(I6,O6))]:
    S=solve(I)
    print(name,S==O)
    d_=[(r,c,I[r][c],S[r][c],O[r][c]) for r in range(len(I)) for c in range(len(I[0])) if S[r][c]!=O[r][c]]
    print(d_[:20], len(d_))

